# GENERATED by `npx ray gen` from implementation/physics.ray - do not edit
# what the rules come to, as something to look up: every theorem, keyed by theory and then by question

# every theorem, as a nested list (read once, from the package's inst/theorems.json)
theorems <- local({
  proved_ <- NULL
  function() {
    if (is.null(proved_)) {
      path <- system.file("theorems.json", package = "orbitmines")
      if (!nzchar(path)) path <- file.path(getOption("orbitmines.root", "languages/physics.r"), "inst", "theorems.json")
      proved_ <<- jsonlite::fromJSON(path, simplifyVector = FALSE)
    }
    proved_
  }
})
# one theorem, or NULL - and never an error
proved <- function(of, theory, theorem) of[[theory]][[theorem]]
# which theories have an answer to a question
theories <- function(of, theorem) Filter(function(t) !is.null(of[[t]][[theorem]]), names(of))
# every question a theory answers
asked <- function(of, theory) names(of[[theory]])
